const PUBLICAS = ['fecha', 'turno', 'linea', 'operario', 'metros', 'objetivo', 'eficiencia', 'parada_averia',
  'parada_cambio_formato', 'parada_falta_material', 'parada_otros', 'paradas_total', 'motivo_principal',
  'aviso', 'observaciones', 'registrado_en'];

// Devuelve la última semana de la planta de ejemplo (común a todos, solo los turnos ya terminados)
// y debajo los informes del visitante, en el orden en que los envió y marcados como suyos. Nunca expone el sid.
const q = $('Listar').first().json.query ?? {};
const sid = /^[a-f0-9]{32}$/.test(String(q.sid ?? '')) ? String(q.sid) : null;
const ahora = Date.now();
const desde = $now.setZone('Europe/Madrid').minus({ days: 6 }).toFormat('yyyy-MM-dd');
const todas = $input.all().map((i) => i.json);
const publica = (r) => {
  const f = { tuya: r.sid !== 'demo' };
  for (const k of PUBLICAS) f[k] = r[k];
  return f;
};
const demo = todas
  .filter((r) => r.sid === 'demo' && r.fecha >= desde && Date.parse(r.registrado_en) <= ahora)
  .sort((a, b) => Date.parse(a.registrado_en) - Date.parse(b.registrado_en));
const propias = sid === null ? [] : todas
  .filter((r) => r.sid === sid)
  .sort((a, b) => Number(a.creado_ms) - Number(b.creado_ms));
return [{ json: { filas: demo.concat(propias).map(publica) } }];

const PUBLICAS = ['fecha', 'turno', 'linea', 'operario', 'metros', 'objetivo', 'eficiencia', 'parada_averia',
  'parada_cambio_formato', 'parada_falta_material', 'parada_otros', 'paradas_total', 'motivo_principal',
  'aviso', 'observaciones', 'registrado_en'];

// Valida el informe del visitante, aplica los topes de la demo y calcula eficiencia y paradas.
const b = $('Crear').first().json.body ?? {};
const filas = $input.all().map((i) => i.json).filter((r) => r.sid);
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
if (filas.filter((r) => r.sid === sid).length >= 20) return fallo('Has llegado al máximo de 20 informes de prueba. Se borran solos a las 2 horas.', 429);
if (filas.filter((r) => r.sid !== 'demo').length >= 400) return fallo('La demo está llena ahora mismo. Vuelve dentro de un rato.', 429);

const fecha = String(b.fecha ?? '');
const d = new Date(fecha + 'T00:00:00Z');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || Number.isNaN(d.getTime()) || d.getUTCFullYear() < 2020 || d.getUTCFullYear() > 2099) return fallo('Fecha: formato AAAA-MM-DD');
if (!['Mañana', 'Tarde', 'Noche'].includes(b.turno)) return fallo('Turno: elige Mañana, Tarde o Noche');
if (!['Perfiladora 1', 'Perfiladora 2', 'Cizalla'].includes(b.linea)) return fallo('Línea: elige una de la lista');

const texto = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);
const operario = texto(b.operario, 40);
if (!operario) return fallo('Operario: escribe un nombre');
const observaciones = texto(b.observaciones, 200);

const num = (v, campo, max) => {
  const n = v === undefined || v === null || v === '' ? 0 : Number(v);
  if (!Number.isFinite(n) || n < 0) throw new Error(`${campo}: tiene que ser un número igual o mayor que 0`);
  if (n > max) throw new Error(`${campo}: máximo ${max}`);
  return n;
};
try {
  const metros = num(b.metros, 'Metros producidos', 1000000);
  const objetivo = num(b.objetivo, 'Objetivo', 1000000);
  if (objetivo === 0) throw new Error('Objetivo: tiene que ser mayor que 0');
  const paradas = {
    'Avería': num(b.parada_averia, 'Parada por avería', 480),
    'Cambio de formato': num(b.parada_cambio_formato, 'Parada por cambio de formato', 480),
    'Falta de material': num(b.parada_falta_material, 'Parada por falta de material', 480),
    'Otros': num(b.parada_otros, 'Parada por otros motivos', 480),
  };
  const total = Object.values(paradas).reduce((a, x) => a + x, 0);
  if (total > 480) throw new Error('Las paradas suman más de 480 minutos: revisa los datos');
  const [motivo, minutos] = Object.entries(paradas).sort((x, y) => y[1] - x[1])[0];
  const eficiencia = Math.round((metros / objetivo) * 1000) / 10;
  return [{ json: { ok: true, fila: {
    sid, fecha, turno: b.turno, linea: b.linea, operario, metros, objetivo, eficiencia,
    parada_averia: paradas['Avería'], parada_cambio_formato: paradas['Cambio de formato'],
    parada_falta_material: paradas['Falta de material'], parada_otros: paradas['Otros'],
    paradas_total: total, motivo_principal: minutos > 0 ? motivo : 'Sin paradas',
    aviso: eficiencia < 80, observaciones,
    registrado_en: $now.setZone('Europe/Madrid').toISO(), creado_ms: Date.now(),
  } } }];
} catch (e) {
  return fallo(e.message);
}

const PUBLICAS = ['fecha', 'turno', 'linea', 'operario', 'metros', 'objetivo', 'eficiencia', 'parada_averia',
  'parada_cambio_formato', 'parada_falta_material', 'parada_otros', 'paradas_total', 'motivo_principal',
  'aviso', 'observaciones', 'registrado_en'];

// Devuelve la fila guardada y el correo que el flujo real enviaría al responsable (misma plantilla que "Preparar correo").
const c = $('Extraer fila').first().json;
const informe = { tuya: true };
for (const k of PUBLICAS) informe[k] = c[k];

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const fmt = (n) => Number(n).toLocaleString('es-ES');
const asunto = `${c.aviso ? '⚠ AVISO · ' : ''}Turno ${c.turno.toLowerCase()} · ${c.linea} · ${c.fecha}: ${String(c.eficiencia).replace('.', ',')} %`;
const color = c.aviso ? '#b42318' : '#067647';
const fila = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#555">${k}</td><td style="padding:4px 0"><b>${v}</b></td></tr>`;
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">
${c.aviso ? `<p style="padding:10px;background:#fef3f2;border-left:4px solid ${color}"><b>Eficiencia por debajo del 80 %.</b> Motivo principal de parada: <b>${esc(c.motivo_principal)}</b>.</p>` : ''}
<p style="font-size:22px;margin:8px 0;color:${color}"><b>${String(c.eficiencia).replace('.', ',')} %</b> de eficiencia</p>
<table>
${fila('Línea', esc(c.linea))}
${fila('Turno', `${esc(c.turno)} · ${esc(c.fecha)}`)}
${fila('Operario', esc(c.operario))}
${fila('Metros', `${fmt(c.metros)} de ${fmt(c.objetivo)}`)}
${fila('Paradas', `${c.paradas_total} min (avería ${c.parada_averia}, cambio de formato ${c.parada_cambio_formato}, falta de material ${c.parada_falta_material}, otros ${c.parada_otros})`)}
${fila('Motivo principal', esc(c.motivo_principal))}
${c.observaciones ? fila('Observaciones', esc(c.observaciones)) : ''}
</table>
<p style="color:#888;font-size:12px">Informe de turno automático · n8n</p>
</div>`;

return [{ json: { ok: true, informe, correo: { de: 'Informe de turno', para: 'Jefe de turno', asunto, html } } }];
